//! MCP server on stdio (JSON-RPC 2.0, one message per line), dual-era: 2026-07-28 clients discover it and
//! send the protocol version with every request; older clients use the initialize handshake.
//! Every command is a tool. Generated by anything-anything from anything.toml.

use crate::commands::{self, Output};
use anyhow::Result;
use serde::de::DeserializeOwned;
use serde_json::{Value, json};
use std::io::{BufRead, Write};

const SUPPORTED: &[&str] = &["2026-07-28", "2025-11-25", "2025-06-18", "2025-03-26"];
const VERSION_KEY: &str = "io.modelcontextprotocol/protocolVersion";
const INSTRUCTIONS: &str = "secrets-anything: Find leaked API keys, tokens, passwords and private keys in any codebase, in any language, before you push. Fast, offline, no false alarms on test fixtures. Tools: secrets_scan, secrets_check, secrets_rules. Every tool returns text for people and, where it has data, structured content.";
const TOOLS: &str = r#"[
  {
    "name": "secrets_scan",
    "description": "Find leaked secrets in a folder or file",
    "inputSchema": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "Folder or file to scan",
          "default": "."
        },
        "all": {
          "type": "boolean",
          "description": "Also report matches in test fixtures and placeholder values"
        }
      },
      "required": [],
      "additionalProperties": false
    }
  },
  {
    "name": "secrets_check",
    "description": "Find leaked secrets in text from stdin",
    "inputSchema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "File name to report the text as; drives the fixture and config-file rules",
          "default": "stdin"
        }
      },
      "required": [],
      "additionalProperties": false
    }
  },
  {
    "name": "secrets_rules",
    "description": "List the built-in detection rules",
    "inputSchema": {
      "type": "object",
      "properties": {},
      "required": [],
      "additionalProperties": false
    }
  }
]"#;

fn call<A: DeserializeOwned>(arguments: &Value, run: fn(&A) -> Result<Output>) -> Result<Output> {
    let arguments = if arguments.is_null() { json!({}) } else { arguments.clone() };
    run(&serde_json::from_value(arguments)?)
}

fn dispatch(name: &str, arguments: &Value) -> Option<Result<Output>> {
    Some(match name {
        "secrets_scan" => call::<commands::args::ScanArgs>(arguments, commands::scan::run),
        "secrets_check" => call::<commands::args::CheckArgs>(arguments, commands::check::run),
        "secrets_rules" => call::<commands::args::RulesArgs>(arguments, commands::rules::run),
        _ => return None,
    })
}

fn info() -> Value {
    json!({ "name": env!("CARGO_PKG_NAME"), "version": env!("CARGO_PKG_VERSION") })
}

fn error(id: Value, code: i64, message: &str, data: Option<Value>) -> Value {
    let mut e = json!({ "code": code, "message": message });
    if let Some(d) = data {
        e["data"] = d;
    }
    json!({ "jsonrpc": "2.0", "id": id, "error": e })
}

fn handle(msg: &Value) -> Option<Value> {
    let id = msg.get("id")?.clone();
    let params = &msg["params"];
    if let Some(v) = params["_meta"][VERSION_KEY].as_str()
        && !SUPPORTED.contains(&v)
    {
        let data = json!({ "supported": SUPPORTED, "requested": v });
        return Some(error(id, -32022, "Unsupported protocol version", Some(data)));
    }
    let result = match msg["method"].as_str().unwrap_or_default() {
        "server/discover" => json!({
            "resultType": "complete",
            "supportedVersions": SUPPORTED,
            "capabilities": { "tools": {} },
            "instructions": INSTRUCTIONS,
            "ttlMs": 3_600_000,
            "cacheScope": "public",
            "_meta": { "io.modelcontextprotocol/serverInfo": info() },
        }),
        "initialize" => {
            let asked = params["protocolVersion"].as_str().unwrap_or("2025-11-25");
            let version = if SUPPORTED.contains(&asked) { asked } else { "2025-11-25" };
            json!({ "protocolVersion": version, "capabilities": { "tools": {} }, "serverInfo": info(), "instructions": INSTRUCTIONS })
        }
        "ping" => json!({}),
        "tools/list" => {
            let tools: Value = serde_json::from_str(TOOLS).unwrap_or_default();
            json!({ "resultType": "complete", "tools": tools, "ttlMs": 300_000, "cacheScope": "public" })
        }
        "tools/call" => {
            let name = params["name"].as_str().unwrap_or_default();
            let Some(result) = dispatch(name, &params["arguments"]) else {
                return Some(error(id, -32602, &format!("unknown tool {name}"), None));
            };
            match result {
                Ok(out) => {
                    let text = if out.text.is_empty() {
                        serde_json::to_string_pretty(&out.data).unwrap_or_default()
                    } else {
                        out.text
                    };
                    let mut r = json!({ "resultType": "complete", "content": [{ "type": "text", "text": text }], "isError": false });
                    if !out.data.is_null() {
                        r["structuredContent"] = out.data;
                    }
                    r
                }
                Err(e) => json!({
                    "resultType": "complete",
                    "content": [{ "type": "text", "text": format!("{e:#}") }],
                    "isError": true,
                }),
            }
        }
        method => return Some(error(id, -32601, &format!("unknown method {method}"), None)),
    };
    Some(json!({ "jsonrpc": "2.0", "id": id, "result": result }))
}

pub fn serve() -> Result<()> {
    let stdin = std::io::stdin();
    for line in stdin.lock().lines() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let reply = match serde_json::from_str::<Value>(&line) {
            Ok(msg) => handle(&msg),
            Err(e) => Some(error(Value::Null, -32700, &e.to_string(), None)),
        };
        if let Some(reply) = reply {
            let mut out = std::io::stdout().lock();
            writeln!(out, "{reply}")?;
            out.flush()?;
        }
    }
    Ok(())
}
